// Study notes: docs/learning/notes/main/inventory/InventoryRepository.kt.md

package com.robertwoolbright.inventory.inventory

import org.springframework.jdbc.core.simple.JdbcClient
import org.springframework.stereotype.Repository


/** Reads and writes inventory rows from Postgres, used by the service layer. */
@Repository
class InventoryRepository(
    private val jdbcClient: JdbcClient,
){

    /** Returns every SKU with its quantity, sorted by SKU id; zero-stock SKUs included, empty list when none. */
    fun findAll(): List<InventoryItem> = jdbcClient.sql("SELECT sku_id, quantity FROM inventory ORDER BY sku_id")

    // Why: Chose the result set lambda instead of InventoryItem::class.java so Kotlin sees the items as non null.
            .query { rs, _ -> 
                InventoryItem(rs.getString("sku_id"), rs.getInt("quantity"))
            }
            .list()


    /** Returns a SKU with its quantity for a specific SKU. Will return null if no such SKU exists */        
    fun findBySkuId(skuId: String): InventoryItem? = jdbcClient.sql("SELECT sku_id, quantity FROM inventory WHERE sku_id = :skuId")

    // Why: We parameterized the skuid instead of adding it directly to the sql above for sql injection prevention. 
            .param("skuId", skuId)
            .query{rs, _ ->
                InventoryItem(skuId = rs.getString("sku_id"), quantity = rs.getInt("quantity"))
            }
    // Why: The list singleOrNull below, we did this over the Java optional so we can stay within kotlin. We wont have more than one entry in the list because sku_id is the primary key so it is unique.
            .list().singleOrNull()


    /**
     * Adds quantity to a SKU's stock, creating the SKU if it doesn't exist yet, and returns the row with the new total.
     * Returns null, changing nothing, only if the new total would go past Int.MAX_VALUE. Quantity must be at least 1.
     */
    fun addStock(skuId: String, quantity: Int): InventoryItem? = jdbcClient.sql(
    // Why: one upsert instead of find-then-insert, so concurrent requests can't race each other.
    // Why: the overflow guard in the WHERE clause is written as current <= MAX - new, because current + new would itself overflow in Postgres.
        """ 
            INSERT INTO inventory (sku_id, quantity)  
                VALUES (:skuId, :quantity) 
                    ON CONFLICT (sku_id) 
                        DO UPDATE SET quantity = inventory.quantity + EXCLUDED.quantity  
                            WHERE inventory.quantity <= :maxQuantity - EXCLUDED.quantity 
                                RETURNING sku_id, quantity
                """
    )
            .param("skuId", skuId)
            .param("quantity", quantity)
            .param("maxQuantity", Int.MAX_VALUE)
            .query{rs, _ ->
                InventoryItem(skuId = rs.getString("sku_id"), quantity = rs.getInt("quantity"))
            }
            .list().singleOrNull()


    /** 
     * Removes the requested quantity because of a purchase from the SKU's stock.
     * Quantity must be at least 1.
     * Returns [PurchaseResult.Purchased] with the remaining stock if successful, [PurchaseResult.InsufficientStock] if there is not enough quantity, [PurchaseResult.SkuNotFound] if the skuId doesn't exist.
     */
    fun removeStock(skuId: String, quantity: Int): PurchaseResult = jdbcClient.sql(
        // Why: One statement instead of 2 (update then select) so we don't deal with between the two statements another request changing the stock. A race condition.
        """
            WITH purchased AS (
                UPDATE inventory SET quantity = quantity - :requested_quantity
                    WHERE sku_id = :skuId AND quantity >= :requested_quantity
                        RETURNING quantity
            )
            SELECT 
                (SELECT quantity FROM purchased) AS remaining_quantity,
                    EXISTS (SELECT 1 FROM inventory WHERE sku_id = :skuId) AS sku_exists
        """
        )
        .param("skuId", skuId)
        .param("requested_quantity", quantity)
        .query{rs, _ ->
                // Why: Used the javaObjectType so null stays null. JDBC getInt would turn null into 0, but 0 is a valid use case here. Meaning the last unit was just sold now the stock is 0. Null would be nothing was bought. We need to keep these distinct.
                val remainingQuantity: Int? = rs.getObject("remaining_quantity", Int::class.javaObjectType) 
                    val skuExists = rs.getBoolean("sku_exists")
                        when {
                            remainingQuantity != null -> PurchaseResult.Purchased(InventoryItem(skuId, remainingQuantity))
                            skuExists -> PurchaseResult.InsufficientStock
                            else -> PurchaseResult.SkuNotFound
                        }
        }
        .single()
}

// Study notes: docs/learning/notes/test/inventory/InventoryConcurrencyTest.kt.md
package com.robertwoolbright.inventory.inventory

import com.robertwoolbright.inventory.support.TestcontainersConfiguration
import org.junit.jupiter.api.BeforeEach
import org.junit.jupiter.api.RepeatedTest
import org.springframework.beans.factory.annotation.Autowired
import org.springframework.boot.test.context.SpringBootTest
import org.springframework.context.annotation.Import
import org.springframework.jdbc.core.simple.JdbcClient
import java.util.concurrent.Callable
import java.util.concurrent.CountDownLatch
import java.util.concurrent.Executors
import java.util.concurrent.TimeUnit
import kotlin.test.assertEquals
import kotlin.test.assertTrue

// Why: @SpringBootTest, not @JdbcTest. @JdbcTest's rolled-back transaction belongs to the test thread
// only: rows it inserts stay invisible to the worker threads, and the workers' commits escape the rollback.
/**
 * Oversell test plan, concurrency section: many threads change the same SKU at the same moment
 * through [InventoryRepository], and no update may be lost or fail. Covers the new-SKU creation
 * race, concurrent restocks of an existing SKU, and the purchase races: same-size buyers, uneven
 * quantities, and restocks mixed with purchases. No race may ever oversell.
 */
@SpringBootTest
@Import(TestcontainersConfiguration::class)
class InventoryConcurrencyTest @Autowired constructor(
    private val inventoryRepository: InventoryRepository,
    private val jdbcClient: JdbcClient,
) {

    /** Nothing is rolled back here, so every run starts from an empty table. */
    @BeforeEach
    fun clearInventory() {
        jdbcClient.sql("DELETE FROM inventory").update()
    }

    private fun quantityOf(skuId: String): Int? =
        jdbcClient.sql("SELECT quantity FROM inventory WHERE sku_id = ?")
            .param(skuId)
            .query { rs, _ -> rs.getInt("quantity") }
            .list()
            .singleOrNull()

    // Why: a start gate. Every thread first checks in on `ready`, then waits on `start`; releasing
    // `start` once makes them all hit the database together instead of one after another.
    private fun <T> race(threads: Int, action: (Int) -> T): List<Result<T>> {
        val pool = Executors.newFixedThreadPool(threads)
        val ready = CountDownLatch(threads)
        val start = CountDownLatch(1)
        try {
            val futures = (0 until threads).map { i ->
                pool.submit(Callable {
                    ready.countDown()
                    start.await()
                    action(i)
                })
            }
            ready.await()
            start.countDown()
            return futures.map { runCatching { it.get(30, TimeUnit.SECONDS) } }
        } finally {
            pool.shutdownNow()
        }
    }

    /**
     * New-SKU race: every first-time add for a missing SKU succeeds (no duplicate-key error from
     * two INSERTs colliding) and the final quantity is the sum of all of them.
     */
    @RepeatedTest(5)
    fun `concurrent first-time adds for a new SKU all succeed and sum up`() {
        val threads = 50

        val results = race(threads) { i -> inventoryRepository.addStock("new-sku", i + 1) }

        val failures = results.mapNotNull { it.exceptionOrNull() }
        assertTrue(failures.isEmpty(), "adds failed: $failures")
        assertTrue(results.all { it.getOrNull() != null }, "an add returned null (treated as overflow)")
        assertEquals((1..threads).sum(), quantityOf("new-sku"))
    }

    /** Lost-update race: concurrent restocks of one existing SKU all count; none overwrites another. */
    @RepeatedTest(5)
    fun `concurrent adds to an existing SKU are never lost`() {
        jdbcClient.sql("INSERT INTO inventory (sku_id, quantity) VALUES ('widget', 10)").update()
        val threads = 50

        val results = race(threads) { inventoryRepository.addStock("widget", 2) }

        val failures = results.mapNotNull { it.exceptionOrNull() }
        assertTrue(failures.isEmpty(), "adds failed: $failures")
        assertEquals(10 + threads * 2, quantityOf("widget"))
    }

    // Why: the "remaining" values prove each unit was sold exactly once. Two buyers who both read
    // stock 10 and wrote 9 would both see 9, and 0..9 would not come back as a clean set.
    /**
     * Same-SKU purchase race: with stock S and N > S buyers of 1, exactly S succeed, N - S are refused
     * as insufficient stock, and the SKU ends at 0, never negative.
     */
    @RepeatedTest(5)
    fun `concurrent purchases never sell more than the stock`() {
        val stock = 10
        jdbcClient.sql("INSERT INTO inventory (sku_id, quantity) VALUES ('widget', ?)").param(stock).update()
        val threads = 50

        val results = race(threads) { inventoryRepository.removeStock("widget", 1) }

        val failures = results.mapNotNull { it.exceptionOrNull() }
        assertTrue(failures.isEmpty(), "purchases failed: $failures")
        val outcomes = results.map { it.getOrThrow() }
        val remaining = outcomes.filterIsInstance<PurchaseResult.Purchased>().map { it.item.quantity }.sorted()
        assertEquals((0 until stock).toList(), remaining)
        assertEquals(threads - stock, outcomes.count { it == PurchaseResult.InsufficientStock })
        assertEquals(0, quantityOf("widget"))
    }

    /**
     * Uneven quantities: buyers of different sizes race for one SKU. What was sold never exceeds the
     * stock, and the final quantity is exactly the stock minus what was sold.
     */
    @RepeatedTest(5)
    fun `concurrent purchases of different sizes never oversell`() {
        val stock = 100
        jdbcClient.sql("INSERT INTO inventory (sku_id, quantity) VALUES ('widget', ?)").param(stock).update()
        val threads = 50

        val results = race(threads) { i ->
            val quantity = i % 7 + 1
            quantity to inventoryRepository.removeStock("widget", quantity)
        }

        val failures = results.mapNotNull { it.exceptionOrNull() }
        assertTrue(failures.isEmpty(), "purchases failed: $failures")
        val outcomes = results.map { it.getOrThrow() }
        assertTrue(outcomes.none { (_, result) -> result == PurchaseResult.SkuNotFound }, "an existing SKU was reported missing")
        val sold = outcomes.filter { (_, result) -> result is PurchaseResult.Purchased }.sumOf { (quantity, _) -> quantity }
        assertTrue(sold <= stock, "sold $sold of $stock")
        assertEquals(stock - sold, quantityOf("widget"))
    }

    // Why: demand (30 x 5 = 150) exceeds supply (20 + 30 x 3 = 110), so some purchases are refused
    // and the test exercises both outcomes under contention.
    /**
     * Mixed receive and purchase race: restocks and purchases of one SKU interleave. Every restock
     * counts, every successful purchase counts, nothing else changes the stock.
     */
    @RepeatedTest(5)
    fun `concurrent restocks and purchases keep an exact balance`() {
        val initial = 20
        jdbcClient.sql("INSERT INTO inventory (sku_id, quantity) VALUES ('widget', ?)").param(initial).update()
        val threads = 60

        val results = race(threads) { i ->
            if (i % 2 == 0) {
                checkNotNull(inventoryRepository.addStock("widget", 3)) { "restock refused" }
                3
            } else {
                when (inventoryRepository.removeStock("widget", 5)) {
                    is PurchaseResult.Purchased -> -5
                    PurchaseResult.InsufficientStock -> 0
                    PurchaseResult.SkuNotFound -> error("an existing SKU was reported missing")
                }
            }
        }

        val failures = results.mapNotNull { it.exceptionOrNull() }
        assertTrue(failures.isEmpty(), "operations failed: $failures")
        assertEquals(initial + results.sumOf { it.getOrThrow() }, quantityOf("widget"))
    }
}
